let currentCity = 'almaty';
function setCity(key) {
  const c = CITIES[key];
  if (!c) return;
  currentCity = key;
  document.querySelectorAll('#citySel button').forEach(b => b.classList.toggle('on', b.dataset.city === key));
  const addr = document.getElementById('addr');
  if (addr) addr.textContent = c.addr;
  const map = document.getElementById('mapLink');
  if (map) map.href = c.map;
  const p1 = document.getElementById('phone1');
  if (p1) { p1.textContent = c.phone1; p1.href = c.phone1href; }
  const p2 = document.getElementById('phone2');
  if (p2) { p2.textContent = c.phone2; p2.href = c.phone2href; }
  const wa = document.getElementById('wa');
  if (wa) { wa.textContent = c.wa; wa.href = c.wahref; }
  const h = document.getElementById('hours');
  if (h) h.textContent = c.hours;
  const ht = document.getElementById('hoursTop');
  if (ht) ht.textContent = c.hours;
  const wd = document.getElementById('waDrinks');
  if (wd && c.drinksWa) wd.href = c.drinksWa;
  try { localStorage.setItem('bao_city', key); } catch(e) {}
}

document.getElementById('citySel')?.addEventListener('click', e => {
  const btn = e.target.closest('button[data-city]');
  if (btn) setCity(btn.dataset.city);
});

// restore
try {
  const saved = localStorage.getItem('bao_city');
  if (saved && CITIES[saved]) setCity(saved);
  else setCity('almaty');
} catch(e) { setCity('almaty'); }



