var D={},ORDER=[];
RAW.split("\n").forEach(function(l){var p=l.split("|");if(!D[p[0]]){D[p[0]]=[];ORDER.push(p[0])}D[p[0]].push({n:p[1],d:p[2],p:+p[3],s:p[4]==="s",img:IMGMAP[p[1]]||""});});
function fmt(n){return String(n).replace(/\B(?=(\d{3})+(?!\d))/g," ")+" тг"}
function show(c){
  document.getElementById("bar").innerHTML=ORDER.map(function(k){return '<button class="cb'+(k===c?' on':'')+'" data-c="'+k+'">'+k+'</button>'}).join("");
  var g=document.getElementById("grid");
  g.className="dishes bao-anim";
  // force reflow for animation restart
  void g.offsetWidth;
  g.innerHTML=D[c].map(function(x,i){
    var ic=(c==="Закуски"||c==="Салаты")&&i%3==1?"bowl":IC[c];
    return '<div class="dish">'+(x.s?'<span class="hot">Острое</span>':'')+(x.img?'<img class="dish-photo" src="images/menu/'+x.img+'" alt="" loading="lazy">':'')+'<h4>'+x.n+'</h4><p>'+(x.d||"")+'</p><div class="row"><span class="price">'+fmt(x.p)+'</span><button class="add" type="button" data-add="'+x.n.replace(/"/g,"&quot;")+'|'+x.p+'">В корзину</button></div></div>';
  }).join("");
}
function find(t){t=t.toLowerCase();return ORDER.filter(function(k){return k.toLowerCase()===t})[0]}
