var C={},step=0,mode="Доставка",pay="Наличными",KEY="bao-cart-v1";
try{C=JSON.parse(localStorage.getItem(KEY)||"{}")}catch(e){C={}}
var $=function(i){return document.getElementById(i)};
function save(){try{localStorage.setItem(KEY,JSON.stringify(C))}catch(e){}}
function total(){var s=0,n=0;for(var k in C){s+=C[k].p*C[k].q;n+=C[k].q}return{s:s,n:n}}
function toast(t){var e=$("toast");e.textContent=t;e.classList.add("on");clearTimeout(toast.t);toast.t=setTimeout(function(){e.classList.remove("on")},1600)}
function openC(){step=0;draw();$("dr").classList.add("on");$("ov").classList.add("on")}
function closeC(){$("dr").classList.remove("on");$("ov").classList.remove("on")}
function esc(s){return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/"/g,"&quot;")}
function draw(){
  var t=total(),keys=Object.keys(C);$("cnt").textContent=t.n;
  $("sum").textContent=fmt(t.s);
  $("foot").style.display=keys.length?"block":"none";
  var el=$("items");
  if(!keys.length){el.innerHTML='<div class="empty">Корзина пуста. Добавьте блюда из меню.</div>';return}
  if(step===0){
    el.innerHTML=keys.map(function(k){var i=C[k];return '<div class="it"><b>'+esc(i.n)+'</b><span class="pr">'+fmt(i.p*i.q)+'</span><span class="q"><button data-q="-1" data-k="'+esc(k)+'">−</button>'+i.q+'<button data-q="1" data-k="'+esc(k)+'">+</button></span><span></span></div>'}).join("");
    $("next").textContent="Оформить заказ";
  }else{
    el.innerHTML='<div class="seg"><button data-m="Доставка" class="'+(mode==="Доставка"?"on":"")+'">Доставка</button><button data-m="Самовывоз" class="'+(mode==="Самовывоз"?"on":"")+'">Самовывоз</button></div>'
    +'<input class="fld" id="fn" placeholder="Ваше имя" autocomplete="name">'
    +'<input class="fld" id="fp" placeholder="Телефон" inputmode="tel" autocomplete="tel" value="+7 ">'
    +(mode==="Доставка"?'<input class="fld" id="fs" placeholder="Улица"><div class="r2"><input class="fld" id="fh" placeholder="Дом"><input class="fld" id="ff" placeholder="Квартира / офис"></div>':(function(){var a=(typeof CITIES!=='undefined'&&CITIES[currentCity])?CITIES[currentCity].addr:'просп. Назарбаева 77, Алматы';return '<div class="note" style="text-align:left;margin:0 0 10px">Заберёте заказ в ресторане: '+a+'</div>';})())
    +'<div class="seg"><button data-p="Наличными" class="'+(pay==="Наличными"?"on":"")+'">Наличными</button><button data-p="Картой" class="'+(pay==="Картой"?"on":"")+'">Картой</button></div>'
    +'<textarea class="fld" id="fc" rows="2" placeholder="Комментарий к заказу"></textarea>'
    +'<div class="note" style="text-align:left">Заказ уйдёт в WhatsApp ресторана. Оператор подтвердит время и стоимость доставки.</div>';
    $("next").textContent="Отправить заказ";
  }
}
function send(){
  var f=function(i){var e=$(i);return e?e.value.trim():""},bad=false;
  var ph=f("fp").replace(/\D/g,"");
  [["fn",f("fn").length<2],["fp",ph.length<10]].concat(mode==="Доставка"?[["fs",!f("fs")],["fh",!f("fh")]]:[]).forEach(function(r){var e=$(r[0]);e.classList.toggle("err",r[1]);if(r[1])bad=true});
  if(bad){toast("Заполните выделенные поля");return}
  var cityName = (typeof CITIES !== "undefined" && CITIES[currentCity]) ? CITIES[currentCity].name : "Алматы";
  var t=total(),L=["Новый заказ с сайта BAO","","Город: "+cityName,mode+(mode==="Доставка"?": "+f("fs")+", д. "+f("fh")+(f("ff")?", кв/оф "+f("ff"):""):""),"Имя: "+f("fn"),"Телефон: "+f("fp"),"Оплата: "+pay,""];
  Object.keys(C).forEach(function(k){L.push(C[k].n+" × "+C[k].q+" = "+fmt(C[k].p*C[k].q))});
  L.push("","Итого: "+fmt(t.s));if(f("fc"))L.push("Комментарий: "+f("fc"));
  window.open("https://wa.me/77757899659?text="+encodeURIComponent(L.join("\n")),"_blank");
  C={};save();step=0;draw();closeC();toast("Заказ отправлен в WhatsApp");
}
document.addEventListener("click",function(e){
  var b;
  if(b=e.target.closest("[data-add]")){var p=b.dataset.add.split("|"),k=p[0];C[k]=C[k]||{n:k,p:+p[1],q:0};C[k].q++;save();draw();toast("Добавлено: "+k);return}
  if(b=e.target.closest("[data-q]")){var k2=b.dataset.k;C[k2].q+=+b.dataset.q;if(C[k2].q<1)delete C[k2];save();draw();return}
  if(b=e.target.closest("[data-m]")){mode=b.dataset.m;var s=[f2("fn"),f2("fp")];draw();return}
  if(b=e.target.closest("[data-p]")){pay=b.dataset.p;draw();return}
  if(e.target.closest("#cartOpen"))return openC();
  if(e.target.closest("#cartClose")||e.target===$("ov"))return closeC();
  if(e.target.closest("#next")){if(step===0){step=1;draw()}else send()}
});
function f2(i){var e=$(i);return e?e.value:""}
draw();
